AND `faturamento_pedido`.`data_faturamento` <= '2024-05-01' UNION SELECT `cliente`.*, "Frente de Caixa" as `tipo_venda`, `venda_caixa`.`data_caixa` as `data_venda`, `venda_caixa`.`num_venda_caixa` `num_venda`, `venda_caixa`.`num_venda_caixa` as `num_venda`, `venda_caixa`.`valor_bruto`, `venda_caixa`.`valor_frete`, 0 as `valor_seguro`, 0 as `outras_despesas`, if(venda_caixa.tipo_desconto = 1, `venda_caixa`.`valor_desconto`, venda_caixa.valor_bruto * (venda_caixa.valor_desconto / 100)) valor_desconto
