FROM (SELECT `cliente`.*, "Pedido Venda" as `tipo_venda`, `faturamento_pedido`.`data_faturamento` as `data_venda`, `pedido_venda`.`num_pedido_venda` `num_venda`, `faturamento_pedido`.`cod_faturamento_pedido` as `num_faturamento`, `faturamento_pedido`.`cod_vendedor`, `faturamento_pedido`.`perc_comissao`, `vendedor`.`nome_vendedor`, `faturamento_pedido`.`valor_bruto`, `faturamento_pedido`.`valor_frete`, `faturamento_pedido`.`valor_seguro`, `faturamento_pedido`.`outras_despesas`, `faturamento_pedido`.`valor_desconto`, `usuario`.`nome_usuario`, `faturamento_pedido`.`cod_transportador`, `transportador`.`nome_transportador`
FROM `faturamento_pedido`
JOIN `pedido_venda` ON `pedido_venda`.`num_pedido_venda` = `faturamento_pedido`.`num_pedido_venda`
JOIN `cliente` ON `cliente`.`cod_cliente` = `pedido_venda`.`cod_cliente`
LEFT JOIN `vendedor` ON `vendedor`.`cod_vendedor` = `faturamento_pedido`.`cod_vendedor`
LEFT JOIN `usuario` ON `usuario`.`email` = `faturamento_pedido`.`usuario`
LEFT JOIN `transportador` ON `transportador`.`cod_transportador` = `faturamento_pedido`.`cod_transportador`
WHERE `pedido_venda`.`id_empresa` = '48'
AND `cliente`.`id_empresa` = '48'
AND `faturamento_pedido`.`estornado` = '0'
AND `faturamento_pedido`.`data_faturamento` >= '2024-04-01'
AND `faturamento_pedido`.`data_faturamento` <= '2024-05-01' UNION SELECT `cliente`.*, "Frente de Caixa" as `tipo_venda`, `venda_caixa`.`data_caixa` as `data_venda`, `venda_caixa`.`num_venda_caixa` `num_venda`, `venda_caixa`.`num_venda_caixa` as `num_faturamento`, `null` as `cod_vendedor`, 0 as `perc_comissao`, " " as `nome_vendedor`, `venda_caixa`.`valor_bruto`, `venda_caixa`.`valor_frete`, 0 as `valor_seguro`, 0 as `outras_despesas`, if(venda_caixa.tipo_desconto = 1, `venda_caixa`.`valor_desconto`, venda_caixa.valor_bruto * (venda_caixa.valor_desconto / 100)) valor_desconto, `usuario`.`nome_usuario`, `venda_caixa`.`cod_transportador`, `transportador`.`nome_transportador`
FROM `venda_caixa`
LEFT JOIN `cliente` ON `cliente`.`cod_cliente` = `venda_caixa`.`cod_cliente` and `cliente`.`id_empresa` = 48
LEFT JOIN `usuario` ON `usuario`.`email` = `venda_caixa`.`usuario`
LEFT JOIN `transportador` ON `transportador`.`cod_transportador` = `venda_caixa`.`cod_transportador`
WHERE `venda_caixa`.`id_empresa` = '48'
AND `venda_caixa`.`status` = '2'
AND `venda_caixa`.`data_caixa` >= '2024-04-01'
AND `venda_caixa`.`data_caixa` <= '2024-05-01') vendas
ORDER BY `vendas`.`data_venda` DESC
